def get_workflow_name(doctype):
	workflow_name = frappe.cache.hget("workflow", doctype)
	if workflow_name is None:
		workflow_name = frappe.db.get_value("Workflow", {"document_type": doctype, "is_active": 1}, "name")
		frappe.cache.hset("workflow", doctype, workflow_name or "")

	return workflow_name

def get_transitions(
	doc: Document | str | dict, workflow: Workflow | None = None, raise_exception: bool = False
) -> list[dict]:
	"""Return list of possible transitions for the given doc"""
	from frappe.model.document import Document

	if not isinstance(doc, Document):
		doc = frappe.get_doc(frappe.parse_json(doc))
		doc.load_from_db()

	if doc.is_new():
		return []

	doc.check_permission("read")

	workflow = workflow or get_workflow(doc.doctype)
	current_state = doc.get(workflow.workflow_state_field)

	if not current_state:
		if raise_exception:
			raise WorkflowStateError
		else:
			frappe.throw(_("Workflow State not set"), WorkflowStateError)

	transitions = []
	roles = frappe.get_roles()

	for transition in workflow.transitions:
		if transition.state == current_state and transition.allowed in roles:
			if not is_transition_condition_satisfied(transition, doc):
				continue
			transitions.append(transition.as_dict())

	return transitions

def get_workflow_safe_globals():
	# access to frappe.db.get_value, frappe.db.get_list, and date time utils.
	return dict(
		frappe=frappe._dict(
			db=frappe._dict(get_value=frappe.db.get_value, get_list=frappe.db.get_list),
			session=frappe.session,
			utils=frappe._dict(
				now_datetime=frappe.utils.now_datetime,
				add_to_date=frappe.utils.add_to_date,
				get_datetime=frappe.utils.get_datetime,
				now=frappe.utils.now,
			),
		)
	)

def is_transition_condition_satisfied(transition, doc) -> bool:
	if not transition.condition:
		return True
	else:
		return frappe.safe_eval(transition.condition, get_workflow_safe_globals(), dict(doc=doc.as_dict()))

def evaluate_workflow_value(value, evaluate_as_expression, doc):
	if not value:
		return None
	if evaluate_as_expression:
		try:
			return frappe.safe_eval(value, get_workflow_safe_globals(), dict(doc=doc.as_dict()))
		except Exception as e:
			frappe.throw(
				_("Invalid expression in Workflow Update Value: {0}").format(str(e)),
				title=_("Workflow Evaluation Error"),
			)
	else:
		return value

def can_cancel_document(doctype: str):
	workflow = get_workflow(doctype)
	cancelling_states = [s.state for s in workflow.states if s.doc_status == "2"]
	if not cancelling_states:
		return True

	for transition in workflow.transitions:
		if transition.next_state in cancelling_states:
			return False
	return True

def _bulk_workflow_action(docnames, doctype, action):
	# dictionaries for logging
	failed_transactions = defaultdict(list)
	successful_transactions = defaultdict(list)

	frappe.clear_messages()
	for idx, docname in enumerate(docnames, 1):
		message_dict = {}
		try:
			show_progress(docnames, _("Applying: {0}").format(action), idx, docname)
			apply_workflow(frappe.get_doc(doctype, docname), action)
			frappe.db.commit()
		except Exception as e:
			if not frappe.message_log:
				# Exception is	raised manually and not from msgprint or throw
				message = f"{e.__class__.__name__}"
				if e.args:
					message += f" : {e.args[0]}"
				message_dict = {"docname": docname, "message": message}
				failed_transactions[docname].append(message_dict)

			frappe.db.rollback()
			frappe.log_error(
				title=f"Workflow {action} threw an error for {doctype} {docname}",
				reference_doctype="Workflow",
				reference_name=action,
			)
		finally:
			if not message_dict:
				if frappe.message_log:
					messages = frappe.get_message_log()
					for message in messages:
						frappe.message_log.pop()
						message_dict = {"docname": docname, "message": message.get("message")}

						if message.get("raise_exception", False) or "Error" in message.get("message", ""):
							failed_transactions[docname].append(message_dict)
						else:
							successful_transactions[docname].append(message_dict)
				else:
					successful_transactions[docname].append({"docname": docname, "message": None})

	if failed_transactions and successful_transactions:
		indicator = "orange"
	elif failed_transactions:
		indicator = "red"
	else:
		indicator = "green"

	print_workflow_log(failed_transactions, _("Failed Transactions"), doctype, indicator)
	print_workflow_log(successful_transactions, _("Successful Transactions"), doctype, indicator)

def print_workflow_log(messages, title, doctype, indicator):
	if messages.keys():
		msg = f"<h4>{title}</h4>"

		for doc in messages.keys():
			if len(messages[doc]):
				html = f"<details><summary>{frappe.utils.get_link_to_form(doctype, doc)}</summary>"
				for log in messages[doc]:
					if log.get("message"):
						html += "<div class='small text-muted' style='padding:2.5px'>{}</div>".format(
							log.get("message")
						)
				html += "</details>"
			else:
				html = f"<div>{doc}</div>"
			msg += html

		frappe.msgprint(
			msg, title=_("Workflow Status"), indicator=indicator, is_minimizable=True, realtime=True
		)

def get_common_transition_actions(docs: str | list[dict[str, Any]], doctype: str):
	common_actions = []
	if isinstance(docs, str):
		docs = json.loads(docs)
	try:
		for i, doc in enumerate(docs, 1):
			if not doc.get("doctype"):
				doc["doctype"] = doctype
			actions = [
				t.get("action")
				for t in get_transitions(doc, raise_exception=True)
				if has_approval_access(frappe.session.user, doc, t)
			]
			if not actions:
				return []
			common_actions = actions if i == 1 else set(common_actions).intersection(actions)
			if not common_actions:
				return []
	except WorkflowStateError:
		pass

	return list(common_actions)

def show_progress(docnames, message, i, description):
	n = len(docnames)
	if n >= 5:
		frappe.publish_progress(float(i) * 100 / n, title=message, description=description)

def set_workflow_state_on_action(doc, workflow_name, action):
	workflow = frappe.get_doc("Workflow", workflow_name)
	workflow_state_field = workflow.workflow_state_field

	# If workflow state of doc is already correct, don't set workflow state
	for state in workflow.states:
		if state.state == doc.get(workflow_state_field) and doc.docstatus == cint(state.doc_status):
			return

	action_map = {"update_after_submit": "1", "submit": "1", "cancel": "2"}
	docstatus = action_map[action]
	for state in workflow.states:
		if state.doc_status == docstatus:
			doc.set(workflow_state_field, state.state)
			return

def has_permission(doc, user):
	if user == "Administrator":
		return True

	permitted_roles = {permitted_role.role for permitted_role in doc.permitted_roles}
	return not permitted_roles.isdisjoint(frappe.get_roles(user))

def process_workflow_actions(doc, state):
	workflow = get_workflow_name(doc.get("doctype"))
	if not workflow:
		return

	if state == "on_trash":
		clear_workflow_actions(doc.get("doctype"), doc.get("name"))
		return

	if is_workflow_action_already_created(doc):
		return

	update_completed_workflow_actions(doc, workflow=workflow, workflow_state=get_doc_workflow_state(doc))
	clear_doctype_notifications("Workflow Action")

	next_possible_transitions = get_next_possible_transitions(workflow, get_doc_workflow_state(doc), doc)

	if not next_possible_transitions:
		return

	roles = {t.allowed for t in next_possible_transitions}
	create_workflow_actions_for_roles(roles, doc)

	if send_email_alert(workflow) and frappe.db.get_value(
		"Workflow Document State",
		filters={"parent": workflow, "state": get_doc_workflow_state(doc)},
		fieldname="send_email",
	):
		enqueue(
			send_workflow_action_email,
			queue="short",
			doc=doc,
			transitions=next_possible_transitions,
			enqueue_after_commit=True,
			now=frappe.in_test,
		)

def apply_action(
	action: str,
	doctype: str,
	docname: str | int,
	current_state: str,
	user: str | None = None,
	last_modified: str | datetime | None = None,
):
	if not verify_request():
		return

	doc = frappe.get_doc(doctype, docname)
	doc_workflow_state = get_doc_workflow_state(doc)

	if doc_workflow_state == current_state:
		action_link = get_confirm_workflow_action_url(doc, action, user)

		if not last_modified or get_datetime(doc.modified) == get_datetime(last_modified):
			return_action_confirmation_page(doc, action, action_link)
		else:
			return_action_confirmation_page(doc, action, action_link, alert_doc_change=True)

	else:
		return_link_expired_page(doc, doc_workflow_state)

def return_success_page(doc):
	frappe.respond_as_web_page(
		_("Success"),
		_("{0}: {1} is set to state {2}").format(
			doc.get("doctype"), frappe.bold(doc.get("name")), frappe.bold(get_doc_workflow_state(doc))
		),
		indicator_color="green",
	)

def return_link_expired_page(doc, doc_workflow_state):
	user_full_name = get_user_who_set_workflow_state(doc, doc_workflow_state) or frappe.get_value(
		"User", doc.get("modified_by"), "full_name"
	)
	frappe.respond_as_web_page(
		_("Link Expired"),
		_("Document {0} has been set to state {1} by {2}").format(
			frappe.bold(doc.get("name")),
			frappe.bold(doc_workflow_state),
			frappe.bold(
				user_full_name
				if user_full_name
				else frappe.get_value("User", doc.get("modified_by"), "full_name")
			),
		),
		indicator_color="blue",
	)

def update_completed_workflow_actions(doc, user=None, workflow=None, workflow_state=None):
	allowed_roles = get_allowed_roles(user, workflow, workflow_state)
	# There is no transaction leading upto this state
	# so no older actions to complete
	if not allowed_roles:
		return
	if workflow_action := get_workflow_action_by_role(doc, allowed_roles):
		update_completed_workflow_actions_using_role(user, workflow_action)

def get_allowed_roles(user, workflow, workflow_state):
	user = user if user else frappe.session.user

	allowed_roles = frappe.get_all(
		"Workflow Transition",
		fields="allowed",
		filters=[["parent", "=", workflow], ["next_state", "=", workflow_state]],
		pluck="allowed",
	)

	user_roles = set(frappe.get_roles(user))
	return set(allowed_roles).intersection(user_roles)

def get_next_possible_transitions(workflow_name, state, doc=None):
	transitions = frappe.get_all(
		"Workflow Transition",
		fields=["allowed", "action", "state", "allow_self_approval", "next_state", "condition"],
		filters=[["parent", "=", workflow_name], ["state", "=", state]],
	)

	transitions_to_return = []

	for transition in transitions:
		is_next_state_optional = get_state_optional_field_value(workflow_name, transition.next_state)
		# skip transition if next state of the transition is optional
		if is_next_state_optional:
			continue
		if not is_transition_condition_satisfied(transition, doc):
			continue
		transitions_to_return.append(transition)

	return transitions_to_return

def get_users_next_action_data(transitions, doc):
	user_data_map = {}

	@frappe.request_cache
	def user_has_permission(user: str) -> bool:
		from frappe.permissions import has_permission

		return has_permission(doctype=doc, user=user)

	for transition in transitions:
		users = get_users_with_role(transition.allowed)
		filtered_users = [
			user for user in users if has_approval_access(user, doc, transition) and user_has_permission(user)
		]
		if doc.get("owner") in filtered_users and not transition.get("send_email_to_creator"):
			filtered_users.remove(doc.get("owner"))
		for user in filtered_users:
			if not user_data_map.get(user):
				user_data_map[user] = frappe._dict(
					{
						"possible_actions": [],
						"email": frappe.db.get_value("User", user, "email"),
					}
				)

			user_data_map[user].get("possible_actions").append(
				frappe._dict(
					{
						"action_name": transition.action,
						"action_link": get_workflow_action_url(transition.action, doc, user),
					}
				)
			)
	return user_data_map

def create_workflow_actions_for_roles(roles, doc):
	if not roles:
		return
	workflow_action = frappe.get_doc(
		{
			"doctype": "Workflow Action",
			"reference_doctype": doc.get("doctype"),
			"reference_name": doc.get("name"),
			"workflow_state": get_doc_workflow_state(doc),
			"status": "Open",
		}
	)

	for role in roles:
		workflow_action.append("permitted_roles", {"role": role})

	workflow_action.insert(ignore_permissions=True)

def send_workflow_action_email(doc, transitions):
	users_data = get_users_next_action_data(transitions, doc)
	common_args = get_common_email_args(doc)
	message = common_args.pop("message", None)
	for data in users_data.values():
		email_args = {
			"recipients": [data.get("email")],
			"args": {"actions": list(deduplicate_actions(data.get("possible_actions"))), "message": message},
			"reference_name": doc.name,
			"reference_doctype": doc.doctype,
		}
		email_args.update(common_args)
		try:
			frappe.sendmail(**email_args)
		except frappe.OutgoingEmailError:
			# Emails config broken, don't bother retrying next user.
			frappe.log_error("Failed to send workflow action email")
			return

def deduplicate_actions(action_list):
	action_map = {}
	for action_data in action_list:
		if not action_map.get(action_data.action_name):
			action_map[action_data.action_name] = action_data

	return action_map.values()

def get_workflow_action_url(action, doc, user):
	apply_action_method = "/api/method/frappe.workflow.doctype.workflow_action.workflow_action.apply_action"

	params = {
		"doctype": doc.get("doctype"),
		"docname": doc.get("name"),
		"action": action,
		"current_state": get_doc_workflow_state(doc),
		"user": user,
		"last_modified": doc.get("modified"),
	}

	return get_url(apply_action_method + "?" + get_signed_params(params))

def get_confirm_workflow_action_url(doc, action, user):
	confirm_action_method = (
		"/api/method/frappe.workflow.doctype.workflow_action.workflow_action.confirm_action"
	)

	params = {
		"action": action,
		"doctype": doc.get("doctype"),
		"docname": doc.get("name"),
		"user": user,
	}

	return get_url(confirm_action_method + "?" + get_signed_params(params))

def is_workflow_action_already_created(doc):
	# Only an open action means the current state is already being acted upon. Completed ones must not
	# block, or a document re-entering a state it has left gets no new action and no notification.
	return frappe.db.exists(
		{
			"doctype": "Workflow Action",
			"reference_name": doc.get("name"),
			"reference_doctype": doc.get("doctype"),
			"workflow_state": get_doc_workflow_state(doc),
			"status": "Open",
		}
	)

def clear_workflow_actions(doctype, name):
	if not (doctype and name):
		return
	frappe.db.delete(
		"Workflow Action",
		filters={
			"reference_name": name,
			"reference_doctype": doctype,
		},
	)

def get_doc_workflow_state(doc):
	workflow_name = get_workflow_name(doc.get("doctype"))
	workflow_state_field = get_workflow_state_field(workflow_name)
	return doc.get(workflow_state_field)

def get_email_template_from_workflow(doc):
	"""Return next_action_email_template for workflow state (if available) based on doc current workflow state."""
	workflow_name = get_workflow_name(doc.get("doctype"))
	doc_state = get_doc_workflow_state(doc)
	template_name = frappe.db.get_value(
		"Workflow Document State",
		{"parent": workflow_name, "state": doc_state},
		"next_action_email_template",
	)

	if not template_name:
		return

	if isinstance(doc, Document):
		doc = doc.as_dict()
	return frappe.get_doc("Email Template", template_name).get_formatted_email(doc)

def get_state_optional_field_value(workflow_name, state):
	return frappe.get_cached_value(
		"Workflow Document State", {"parent": workflow_name, "state": state}, "is_optional_state"
	)

def job_log_level(status, duration):
    return (logging.ERROR if status != 'done'
        else logging.WARNING if duration > 1
        else logging.INFO if duration > .1
        else logging.DEBUG)

def _keep_to_compute(env, changed_fields):
    """ Keep the computed fields depending on ``changed_fields`` as-is, so that
    they are recomputed once the values of ``changed_fields`` are set.
    """
    to_compute = {
        dep: comp
        for f in changed_fields
        for dep in env.registry.get_dependent_fields(f)
        if (comp := env.records_to_compute(dep))
    }
    yield
    for dep, comp in to_compute.items():
        env.add_to_compute(dep, comp)

def get_webhook_request_payload():
    if not request:
        return None
    try:
        payload = request.get_json_data()
    except ValueError:
        payload = {**request.httprequest.args}
    return payload

def _check_trigger(self):
    for automation in self:
        if automation.trigger in MAIL_TRIGGERS and not automation.model_id.is_mail_thread:
            raise exceptions.ValidationError(_("Mail event can not be configured on model %s. Only models with discussion feature can be used.", automation.model_id.name))

def _check_action_server_model(self):
    for rule in self:
        failing_actions = rule.action_server_ids.filtered(
            lambda action: action.model_id != rule.model_id
        )
        if failing_actions:
            raise exceptions.ValidationError(
                _('Target model of actions %(action_names)s are different from rule model.',
                  action_names=', '.join(failing_actions.mapped('name'))
                 )
            )

def _compute_url(self):
    for automation in self:
        if automation.trigger != "on_webhook":
            automation.url = ""
        else:
            automation.url = "%s/web/hook/%s" % (automation.get_base_url(), automation.webhook_uuid)

def _inverse_model_name(self):
    for rec in self:
        rec.model_id = self.env["ir.model"]._get(rec.model_name)

def _check_time_trigger(self):
    for record in self:
        if record.trigger in TIME_TRIGGERS and record.trg_date_range < 0:
            raise exceptions.ValidationError(_("Delay must be positive. Set 'Delay mode' to 'Before' to negate the delay."))

def _check_trigger_state(self):
    for record in self:
        warning_actions = record.action_server_ids.filtered('warning')
        if warning_actions:
            raise exceptions.ValidationError(
                _("Following child actions have warnings: %(children)s", children=', '.join(warning_actions.mapped('name')))
            )
        no_code_actions = record.action_server_ids.filtered(lambda a: a.state != 'code')
        if record.trigger == 'on_change' and no_code_actions:
            raise exceptions.ValidationError(
                _('"On live update" automation rules can only be used with "Execute Python Code" action type.')
            )
        mail_actions = record.action_server_ids.filtered(
            lambda a: a.state in ['mail_post', 'followers', 'next_activity']
        )
        if record.trigger == 'on_unlink' and mail_actions:
            raise exceptions.ValidationError(
                _('Email, follower or activity action types cannot be used when deleting records, '
                  'as there are no more records to apply these changes to!')
            )

def _compute_action_server_ids(self):
    """ When changing / setting model, remove actions that are not targeting
    the same model anymore. """
    for rule in self.filtered('model_id'):
        actions_to_remove = rule.action_server_ids.filtered(
            lambda action: action.model_id != rule.model_id
        )
        if actions_to_remove:
            rule.action_server_ids = [(3, action.id) for action in actions_to_remove]

def _compute_trg_date_id(self):
    to_reset = self.filtered(lambda a: a.trigger not in TIME_TRIGGERS)
    to_reset.trg_date_id = False
    for record in (self - to_reset):
        record.trg_date_id = record._get_trigger_specific_field()

def _onchange_trg_date_range_data(self):
    if self.trg_date_range < 0:
        self.trg_date_range = abs(self.trg_date_range)
        if self.trigger == 'on_time':
            self.trg_date_range_mode = 'before' if self.trg_date_range_mode == 'after' else 'after'

def _compute_trg_date_range_data(self):
    for record in self:
        if record.trigger not in TIME_TRIGGERS:
            record.trg_date_range = False
            record.trg_date_range_type = False
            record.trg_date_range_mode = False
            continue
        if not record.trg_date_range_type:
            record.trg_date_range_type = 'hour'
        if not record.trg_date_range_mode or record.trigger not in 'on_time':
            record.trg_date_range_mode = 'after'

def _compute_trg_date_calendar_id(self):
    to_reset = self.filtered(
        lambda a: a.trigger not in TIME_TRIGGERS or not a.trg_date_id or a.trg_date_range_type != 'day'
    )
    to_reset.trg_date_calendar_id = False

def _compute_previous_domain(self):
    for automation in self:
        automation.previous_domain = automation.filter_domain

def _compute_on_change_field_ids(self):
    to_reset = self.filtered(lambda a: a.trigger != 'on_change')
    to_reset.on_change_field_ids = False

def _compute_trigger_field_ids(self):
    for rec in self.filtered(lambda a: a.trigger != "on_create_or_write"):
        rec._onchange_trigger()

def _onchange_trigger_or_actions(self):
    no_code_actions = self.action_server_ids.filtered(lambda a: a.state != 'code')
    if self.trigger == 'on_change' and len(no_code_actions) > 0:
        trigger_field = self._fields['trigger']
        action_states = dict(self.action_server_ids._fields['state']._description_selection(self.env))
        return {'warning': {
            'title': _("Warning"),
            'message': _(
                "The \"%(trigger_value)s\" %(trigger_label)s can only be "
                "used with the \"%(state_value)s\" action type",
                trigger_value=dict(trigger_field._description_selection(self.env))['on_change'],
                trigger_label=trigger_field._description_string(self.env),
                state_value=action_states['code'])
        }}

    MAIL_STATES = ('mail_post', 'followers', 'next_activity')
    mail_actions = self.action_server_ids.filtered(lambda a: a.state in MAIL_STATES)
    if self.trigger == 'on_unlink' and len(mail_actions) > 0:
        return {'warning': {
            'title': _("Warning"),
            'message': _(
                "You cannot send an email, add followers or create an activity "
                "for a deleted record.  It simply does not work."
            ),
        }}

def _has_trigger_onchange(self):
    return any(
        automation.active and automation.trigger == 'on_change' and automation.on_change_field_ids
        for automation in self
    )

def write(self, vals: dict):
    clear_templates = self._has_trigger_onchange()
    res = super().write(vals)
    if set(vals).intersection(CRITICAL_FIELDS):
        self._update_cron()
        self._update_registry()
        clear_templates |= self._has_trigger_onchange()
        if clear_templates and any(self._ids):
            # Invalidate templates cache to update on_change attributes if needed
            self.env.transaction.invalidate_ormcache('templates')
    elif set(vals).intersection(RANGE_FIELDS):
        self._update_cron()
    return res

